  Lemma aleft_final : forall k AL, 0 <= k <= 10 -> aleft k <= AL -> TRC26 + as_Cf H (2 ^ 26) <= AL.
  Proof. intros k AL Hk HAL. unfold aleft in HAL. pose proof CU26_nonneg. nia. Qed.

