  Lemma blk_range : forall s p A cap m, as_RHEAP H s [(p, A, cap)] m -> ablock_range H A cap.
  Proof. intros s p A cap m RH. exact (ah_blocks H HH _ _ _ (p, A, cap) RH ltac:(left; reflexivity)). Qed.

