  Lemma read_step : forall s msF mo regs mem p (A len cap : Z) K,
    as_VIS H s msF = mkst regs (Z_to_bv 64 AREAD_STUB) mem rom -> as_AKREL H s (mkCfg msF mo) ->
    ARInv len cap A s p regs mem mo ->
    (forall regs' mem' msF' mo' n,
       as_VIS H s msF' = mkst regs' (Z_to_bv 64 0xa401c) mem' rom -> as_AKREL H s (mkCfg msF' mo') ->
       AMInv len n cap A s p regs' mem' mo' -> realizes bsegs (mkCfg msF' mo') K) ->
    (len = Z.of_nat (length data) -> forall regs' mem' msF' mo',
       as_VIS H s msF' = mkst regs' (Z_to_bv 64 0x11281c) mem' rom -> as_AKREL H s (mkCfg msF' mo') ->
       ACInv cap A s p regs' mem' mo' -> realizes bsegs (mkCfg msF' mo') K) ->
