  Lemma aerrno_rw : forall m regs, getr regs 4 = Z_to_bv 64 ATP -> exists e : word, rw_cells bsegs m (bv_unsigned (getr regs 4) + -164) [C4 e].
  Proof.
    intros m regs H4. rewrite H4, u_small by (unfold ATP; lia). replace (ATP + -164) with AERRNO by reflexivity. apply aerrno_rw_any.
  Qed.

