  Lemma m_refuse : forall s msF mo regs mem p (A len n cap : Z) K,
    as_VIS H s msF = mkst regs (Z_to_bv 64 0xa401c) mem rom -> as_AKREL H s (mkCfg msF mo) ->
    AMInv len n cap A s p regs mem mo -> len + n = cap -> MAX_INPUT <= cap ->
    (forall regs' mem' msF' mo', as_VIS H s msF' = mkst regs' (Z_to_bv 64 0xa41e4) mem' rom -> as_AKREL H s (mkCfg msF' mo') ->
       ARfInv A s p regs' mem' mo' -> realizes bsegs (mkCfg msF' mo') K) ->
    realizes bsegs (mkCfg msF mo) K.
